// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title CrossServiceAuthBridge
 * @notice Handles cross-service authentication tokens with packed encoding
 * @dev Uses tightly packed ABI encoding for gas optimization
 */
contract CrossServiceAuthBridge is Ownable {
    using ECDSA for bytes32;

    struct AuthToken {
        address serviceOrigin;
        address user;
        uint64 expiry;
        uint64 nonce;
        bytes32 scopeHash;
    }

    struct ServiceRegistration {
        address signer;
        uint256 rateLimit;
        uint256 callCount;
        bool active;
    }

    mapping(address => ServiceRegistration) public services;
    mapping(bytes32 => bool) public usedTokens;
    mapping(address => mapping(address => uint256)) public userBalances;

    uint256 public constant MAX_PAYLOAD_FIELDS = 8;
    uint256 public constant FIELD_SIZE = 32;

    event ServiceRegistered(address indexed service, address signer);
    event AuthExecuted(address indexed user, address indexed service, bytes32 tokenId);
    event FundsDeposited(address indexed user, uint256 amount);
    event FundsWithdrawn(address indexed user, address indexed service, uint256 amount);

    constructor() Ownable() {}

    function registerService(address service, address signer, uint256 rateLimit) external onlyOwner {
        require(service != address(0) && signer != address(0), "Invalid addresses");
        services[service] = ServiceRegistration(signer, rateLimit, 0, true);
        emit ServiceRegistered(service, signer);
    }

    function deposit() external payable {
        require(msg.value > 0, "Must deposit nonzero");
        userBalances[msg.sender][address(this)] += msg.value;
        emit FundsDeposited(msg.sender, msg.value);
    }

    /**
     * @notice Validates auth token and executes cross-service withdrawal
     * @param token The authentication token struct
     * @param signature The ECDSA signature from the service signer
     * @param payload Additional calldata fields for the operation
     */
    function executeAuthWithdrawal(
        AuthToken calldata token,
        bytes calldata signature,
        bytes calldata payload
    ) external {
        require(services[token.serviceOrigin].active, "Service not active");
        require(block.timestamp <= token.expiry, "Token expired");

        // Compute token ID for replay protection
        bytes32 tokenId = _computeTokenId(token);
        require(!usedTokens[tokenId], "Token already used");

        // Verify signature from registered service signer
        bytes32 messageHash = _computeMessageHash(token, payload);
        address recovered = messageHash.toEthSignedMessageHash().recover(signature);
        require(recovered == services[token.serviceOrigin].signer, "Invalid signature");

        // Rate limiting
        ServiceRegistration storage svc = services[token.serviceOrigin];
        require(svc.callCount < svc.rateLimit, "Rate limit exceeded");
        svc.callCount++;

        // Mark token as used
        usedTokens[tokenId] = true;

        // Decode withdrawal amount from payload using packed field extraction
        uint256 amount = _extractAmountFromPayload(payload);

        // Execute withdrawal
        require(userBalances[token.user][address(this)] >= amount, "Insufficient balance");
        userBalances[token.user][address(this)] -= amount;

        (bool success, ) = token.user.call{value: amount}("");
        require(success, "Transfer failed");

        emit AuthExecuted(token.user, token.serviceOrigin, tokenId);
        emit FundsWithdrawn(token.user, token.serviceOrigin, amount);
    }

    /**
     * @dev Extracts amount from tightly packed payload
     * Layout: [fieldCount (1 byte)][fieldType (1 byte)][fieldData (variable)]...
     * Field types: 0x01 = uint256 amount, 0x02 = address recipient, 0x03 = bytes32 ref
     */
    function _extractAmountFromPayload(bytes calldata payload) internal pure returns (uint256) {
        require(payload.length >= 1, "Empty payload");

        uint8 fieldCount = uint8(payload[0]);
        require(fieldCount <= MAX_PAYLOAD_FIELDS, "Too many fields");

        uint256 offset = 1;

        for (uint8 i = 0; i < fieldCount; i++) {
            require(offset < payload.length, "Payload underflow");

            uint8 fieldType = uint8(payload[offset]);
            offset += 1;

            if (fieldType == 0x01) {
                // Amount field - extract uint256
                require(offset + 32 <= payload.length, "Amount field overflow");
                uint256 amount;
                bytes calldata slice = payload[offset:offset + 32];
                assembly {
                    amount := calldataload(slice.offset)
                }
                return amount;
            } else if (fieldType == 0x02) {
                // Address field - skip 20 bytes
                offset += 20;
            } else if (fieldType == 0x03) {
                // Bytes32 field - skip 32 bytes
                offset += 32;
            } else if (fieldType == 0x04) {
                // Variable length field: next 2 bytes = length
                require(offset + 2 <= payload.length, "Length field overflow");
                uint16 fieldLen = uint16(uint8(payload[offset])) << 8 | uint16(uint8(payload[offset + 1]));
                offset += 2 + fieldLen;
            } else {
                revert("Unknown field type");
            }
        }

        revert("No amount field found");
    }

    function _computeTokenId(AuthToken calldata token) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(
            token.serviceOrigin,
            token.user,
            token.expiry,
            token.nonce,
            token.scopeHash
        ));
    }

    /**
     * @dev Computes message hash for signature verification
     * Uses abi.encode for unambiguous encoding preventing collision attacks.
     * Includes block.chainid and address(this) to bind the signature to this
     * specific deployment/chain, preventing cross-chain / cross-contract replay.
     */
    function _computeMessageHash(AuthToken calldata token, bytes calldata payload) internal view returns (bytes32) {
        return keccak256(abi.encode(
            block.chainid,
            address(this),
            token.serviceOrigin,
            token.user,
            token.expiry,
            token.nonce,
            token.scopeHash,
            keccak256(payload)
        ));
    }

    function resetRateLimit(address service) external onlyOwner {
        services[service].callCount = 0;
    }

    function deactivateService(address service) external onlyOwner {
        services[service].active = false;
    }

    receive() external payable {
        userBalances[msg.sender][address(this)] += msg.value;
    }
}
